From 76476826b5ee5fe412622a8fbaf4ed52874d0667 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 23:32:14 +0100
Subject: [PATCH] applets/colorpicker: allow opening the color dialog for
 history entries

The color dialog could only be opened from the applet's own context menu,
always starting from the most recent color. Add an "Open Color Dialog"
entry to each history color's menu that opens it with that color instead.

BUG: 457310
---
 applets/colorpicker/qml/ColorContextMenu.qml |  8 +++++++-
 applets/colorpicker/qml/Logic.js             |  3 +++
 applets/colorpicker/qml/main.qml             | 14 ++++++++++++--
 3 files changed, 22 insertions(+), 3 deletions(-)

diff --git a/applets/colorpicker/qml/ColorContextMenu.qml b/applets/colorpicker/qml/ColorContextMenu.qml
index d273ca654..4e320432e 100644
--- a/applets/colorpicker/qml/ColorContextMenu.qml
+++ b/applets/colorpicker/qml/ColorContextMenu.qml
@@ -20,7 +20,13 @@ PlasmaExtras.ModelContextMenu {

     placement: PlasmaExtras.Menu.BottomPosedLeftAlignedPopup

-    onClicked: {
+    signal openColorDialogRequested()
+
+    onClicked: model => {
+        if (model.openColorDialog) {
+            openColorDialogRequested();
+            return;
+        }
         picker.copyToClipboard(model.text)
         colorLabel.visible = false;
         copyIndicatorLabel.visible = true;
diff --git a/applets/colorpicker/qml/Logic.js b/applets/colorpicker/qml/Logic.js
index d5b0064e1..6b48f43f2 100644
--- a/applets/colorpicker/qml/Logic.js
+++ b/applets/colorpicker/qml/Logic.js
@@ -7,6 +7,7 @@
 .pragma library

 var copyToClipboardText = "Copy to Clipboard";
+var openColorDialogText = "Open Color Dialog";

 var formats = [
     "RRR,GGG,BBB",
@@ -57,6 +58,8 @@ function roundComponent(n) {

 function menuForColor(color) {
     return [
+        {text: openColorDialogText, icon: "color-management", openColorDialog: true},
+        {separator: true},
         {text: copyToClipboardText, section: true},
         {text: formatColor(color, "RRR,GGG,BBB")},
         {text: formatColor(color, "rgb")},
diff --git a/applets/colorpicker/qml/main.qml b/applets/colorpicker/qml/main.qml
index f20ff7012..139fdd845 100644
--- a/applets/colorpicker/qml/main.qml
+++ b/applets/colorpicker/qml/main.qml
@@ -41,6 +41,11 @@ PlasmoidItem {
         }
     }

+    function openColorDialog(initialColor) {
+        colorDialogLoader.initialColor = initialColor;
+        colorDialogLoader.active = true;
+    }
+
     function pickColor() {
         root.expanded = false
         picker.pick()
@@ -53,12 +58,15 @@ PlasmoidItem {

     Loader {
         id: colorDialogLoader
+
+        property var initialColor
+
         active: false
         sourceComponent: QtDialogs.ColorDialog {
             id: colorDialog
             modality: Qt.NonModal
             title: Plasmoid.title
-            selectedColor: historyModelItem.count > 0 ? root.recentColor : undefined /* Prevent transparent colors */
+            selectedColor: colorDialogLoader.initialColor ?? (historyModelItem.count > 0 ? root.recentColor : undefined) /* Prevent transparent colors */
             onAccepted: {
                 root.colorPicked(selectedColor);
                 colorDialogLoader.active = false;
@@ -87,7 +95,7 @@ PlasmoidItem {
         PlasmaCore.Action {
             text: i18nc("@action", "Open Color Dialog")
             icon.name: "color-management"
-            onTriggered: colorDialogLoader.active = true
+            onTriggered: root.openColorDialog(undefined)
         },
         PlasmaCore.Action {
             text: i18nc("@action", "Clear History")
@@ -107,6 +115,7 @@ PlasmoidItem {
     Component.onCompleted: {
         Plasmoid.configuration.history.forEach(item => historyModelItem.append({ color: item }));
         Logic.copyToClipboardText = i18ndc("plasma_applet_org.kde.plasma.colorpicker", "@title:menu", "Copy to Clipboard"); // i18n is not supported in js library
+        Logic.openColorDialogText = i18ndc("plasma_applet_org.kde.plasma.colorpicker", "@action:inmenu", "Open Color Dialog");
     }

     compactRepresentation: CompactRepresentation {
@@ -274,6 +283,7 @@ PlasmoidItem {

             function openMenu() {
                 const menu = Logic.createContextMenu(this, delegateMouse.color, picker, colorLabel, copyIndicatorLabel, colorLabelRestoreTimer) as ColorContextMenu;
+                menu.openColorDialogRequested.connect(() => root.openColorDialog(delegateMouse.color));
                 menu.openRelative();
             }

-- 
2.53.0
